import type { AgentId, TaskMode } from '../types';

/**
 * Context passed to each skill to determine relevance and build prompt content.
 */
export interface SkillContext {
  agentId: AgentId;
  mode: TaskMode;
  /** Special workspace action currently being executed, if any. */
  workspaceAction?: 'merge';
  /** Whether this is a resumed session (not the first message). */
  isExistingSession: boolean;
  /** Whether the agent has a native todo/task tool (e.g. Claude Code's TodoWrite). */
  hasNativeTodoTool: boolean;
  /** Whether the workspace branch is auto-generated and needs renaming. */
  isAutoGeneratedBranch: boolean;
  /** Merge task metadata, when the current workspace action is a merge. */
  merge?: {
    targetBranch: string;
    squash: boolean;
  };
  /** Workspace metadata, if present. */
  workspace?: {
    branch: string;
    worktreePath: string;
    parentRepo: string;
    outcome: string;
  };
  /** Persisted attachment context, if attachments were written to `.context/`. */
  attachments?: {
    manifestPath: string;
    imageCount: number;
    fileCount: number;
  };
}

/**
 * A Flux skill is a modular prompt fragment that knows when it's relevant
 * and produces the prompt text to inject.
 */
export interface FluxSkill {
  /** Unique identifier for the skill. */
  id: string;
  /** Human-readable name. */
  name: string;
  /** Returns true if this skill should be active given the context. */
  isRelevant(ctx: SkillContext): boolean;
  /** Build the prompt text to inject. */
  buildPrompt(ctx: SkillContext): string;
}